# recruitment_process_type ----
## Setup ----
# No setup required.

## IO correctness ----
test_that("`recruitment_process_type()` works with correct inputs", {
  #' @description Test that `recruitment_process_type()` returns log_r when the recruitment labels include log_r.
  expect_equal(
    object = FIMS:::recruitment_process_type(c("log_rzero", "log_r")),
    expected = "log_r"
  )
})

## Edge handling ----
# No edge cases to test.

## Error handling ----
test_that("`recruitment_process_type()` returns correct warning messages", {
  #' @description Test that `recruitment_process_type()` warns when both log_devs and log_r are given.
  expect_warning(
    object = FIMS:::recruitment_process_type(
      c("log_rzero", "log_devs", "log_r")
    ),
    regexp = "there can be only one"
  )
  #' @description Test that `recruitment_process_type()` uses log_devs when both log_devs and log_r are given.
  expect_equal(
    object = suppressWarnings(FIMS:::recruitment_process_type(
      c("log_rzero", "log_devs", "log_r")
    )),
    expected = "log_devs"
  )
})
